'use client';

import React, { useState, useEffect } from 'react';
import ProductGrid from '../components/ProductGrid/ProductGrid';
import OrderModal from '../components/OrderModal/OrderModal';
import styles from './page.module.css';
import { Globe, Settings } from 'lucide-react';
import Link from 'next/link';

// Mock Data for Zero-DB Mode
const MOCK_PRODUCTS = [
    {
        id: '1',
        name: 'Premium Sankara Karuvadu (Red Snapper)',
        image: 'https://images.unsplash.com/photo-1544253051-bd2e236528d2?q=80&w=400',
        originalPrice: 450,
        discountPercentage: 10,
        finalPrice: 405,
        category: 'Premium'
    },
    {
        id: '2',
        name: 'Fried Nethili Karuvadu (Anchovies)',
        image: 'https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?q=80&w=400',
        originalPrice: 320,
        discountPercentage: 15,
        finalPrice: 272,
        category: 'Regular'
    },
    {
        id: '3',
        name: 'Large Vanjiram Karuvadu (King Fish)',
        image: 'https://images.unsplash.com/photo-1534447677768-be436bb09401?q=80&w=400',
        originalPrice: 1200,
        discountPercentage: 5,
        finalPrice: 1140,
        category: 'VVIP'
    },
    {
        id: '4',
        name: 'Paal Sura Karuvadu (Milk Shark)',
        image: 'https://images.unsplash.com/photo-1516733725897-1aa73b87c8e8?q=80&w=400',
        originalPrice: 600,
        discountPercentage: 0,
        finalPrice: 600,
        category: 'Special'
    }
];

export default function Home() {
    const [products] = useState(MOCK_PRODUCTS);
    const [selectedProduct, setSelectedProduct] = useState<any>(null);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [language, setLanguage] = useState<'EN' | 'TA'>('EN');

    const handleOpenOrder = (product: any) => {
        setSelectedProduct(product);
        setIsModalOpen(true);
    };

    const handleCloseOrder = () => {
        setIsModalOpen(false);
        setSelectedProduct(null);
    };

    const handleSubmitOrder = async (formData: any) => {
        // In Mock Mode, we just show the Receipt and redirect
        const message = `New Order Received 🐟
Order ID: JK${Math.floor(1000 + Math.random() * 9000)}
Product: ${formData.productName}
Qty: ${formData.quantity} Kg
Customer: ${formData.customerName}
Phone: ${formData.mobileNumber}
Address: ${formData.address}`;

        const encodedMessage = encodeURIComponent(message);
        const whatsappUrl = `https://wa.me/919XXXXXXXXX?text=${encodedMessage}`;
        window.location.href = whatsappUrl;
        handleCloseOrder();
    };

    const texts = {
        EN: {
            heroTitle: 'Authentic Sea-Fresh Dry Fish',
            heroSub: 'From the shores of Thoothukudi to your kitchen doorstep.',
            shopNow: 'Shop Now',
            ourProducts: 'Our Products',
        },
        TA: {
            heroTitle: 'சுவையான கடல் மீன் கருவாடு',
            heroSub: 'தூத்துக்குடி கடற்கரையில் இருந்து உங்கள் இல்லத்திற்கு.',
            shopNow: 'இப்போதே வாங்குங்கள்',
            ourProducts: 'எங்கள் தயாரிப்புகள்',
        }
    };

    return (
        <div className={styles.main}>
            <header className={styles.header}>
                <div className={`container ${styles.headerFlex}`}>
                    <h1 className={styles.logo}>THOOTHUKUDI <br /> <span>JOHN KARUVATTU KADAI</span></h1>
                    <div className={styles.headerActions}>
                        <button className={styles.langToggle} onClick={() => setLanguage(l => l === 'EN' ? 'TA' : 'EN')}>
                            <Globe size={18} />
                            {language === 'EN' ? 'தமிழ்' : 'English'}
                        </button>
                        <Link href="/admin/dashboard" className={styles.adminLink}>
                            <Settings size={18} />
                            Admin
                        </Link>
                    </div>
                </div>
            </header>

            <section className={styles.hero}>
                <div className="container">
                    <div className={styles.heroContent}>
                        <h2>{texts[language].heroTitle}</h2>
                        <p>{texts[language].heroSub}</p>
                        <button className={styles.ctaButton} onClick={() => document.getElementById('products')?.scrollIntoView({ behavior: 'smooth' })}>
                            {texts[language].shopNow}
                        </button>
                    </div>
                </div>
            </section>

            <section id="products" className={styles.products}>
                <div className="container">
                    <h3 className={styles.sectionTitle}>{texts[language].ourProducts}</h3>
                    <ProductGrid
                        products={products}
                        onOrder={(p: any) => handleOpenOrder(p)}
                    />
                </div>
            </section>

            <footer className={styles.footer}>
                <div className="container">
                    <p>&copy; 2024 THOOTHUKUDI JOHN KARUVATTU KADAI. All rights reserved.</p>
                    <p>Contact: +91 9XXXXXXXXX | Email: johnkaruvattukadai@gmail.com</p>
                </div>
            </footer>

            <OrderModal
                product={selectedProduct}
                isOpen={isModalOpen}
                onClose={handleCloseOrder}
                onSubmit={handleSubmitOrder}
            />
        </div>
    );
}
